 */
scwin.chk_secuYn_onclick = function() {
    try {
        if (chk_secuYn.getValue() === "Y") {
            pan_secu.show("");
            cmb_KONEX_SECU_ISU_METHD_TP_CD.setValue('1');
            cmb_ISU_SCHDL_STK_KIND_CD.setValue('00');
        } else {
            pan_secu.hide();
            /*dts_secuIsu.setNameValue(1, "KONEX_SECU_ISU_METHD_TP_CD","") ;
            dts_secuIsu.setNameValue(1, "ISU_SCHDL_STK_KIND_CD","") ;
            dts_secuIsu.setNameValue(1, "ISU_SCHDL_SHRS","") ;
            dts_secuIsu.setNameValue(1, "ISU_NXT_SHRS","") ;
            dts_secuIsu.setNameValue(1, "ISU_NXT_CAP","") ;
            dts_secuIsu.setNameValue(1, "PAY_SCHDL_DD","") ;*/
            cmb_KONEX_SECU_ISU_METHD_TP_CD.setValue('');
            cmb_ISU_SCHDL_STK_KIND_CD.setValue('');
            edt_ISU_SCHDL_SHRS.setValue('');
            edt_ISU_NXT_SHRS.setValue('');
            edt_ISU_NXT_CAP.setValue('');
            edt_PAY_SCHDL_DD.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05015.chk_secuYn_onclick" });
    }
};

/**
             * @method
             * @name trs_Save_OnFail
