///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchSecuIsu
 * @description search Secu Isu 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchSecuIsu = async function() {
    const parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    let url;

    const sbmOptions = {
        id : "sbm_dts_secuIsu",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_secuIsu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_secuIsu.getRowCount() === 0) {
        buttonSet.setInsertStatus();
        const sbmOptions = {
            id : "sbm_dts_secuIsu",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_secuIsu=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_secuIsu.insertRow();
        chk_secuYn.setValue('Y');
        dts_secuIsu.setCellData("1", "KONEX_SECU_ISU_METHD_TP_CD", "1");
        dts_secuIsu.setCellData("1", "ISU_SCHDL_STK_KIND_CD", "00");
        edt_ISU_SCHDL_SHRS.setValue('');
        edt_ISU_NXT_SHRS.setValue('');
        edt_ISU_NXT_CAP.setValue('');
        edt_PAY_SCHDL_DD.setValue('');
    } else {
        if (dts_secuIsu.getCellData(1, "KONEX_SECU_ISU_YN") === "Y") {
            pan_secu.show("");
            chk_secuYn.setValue('Y');
        } else {
            pan_secu.hide();
            chk_secuYn.setValue('N');
            cmb_KONEX_SECU_ISU_METHD_TP_CD.setValue('');
            cmb_ISU_SCHDL_STK_KIND_CD.setValue('');
            edt_ISU_SCHDL_SHRS.setValue('');
            edt_ISU_NXT_SHRS.setValue('');
            edt_ISU_NXT_CAP.setValue('');
            edt_PAY_SCHDL_DD.setValue('');
        }
        buttonSet.setUpdateStatus();
    }
};

/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    03346 - 코넥스증권발행방식
    00391 - 주식종류
     */
    const arrCid = [{
        cid: "KONEX_SECU_ISU_METHD_TP_CD",
        cnm: "cmb_KONEX_SECU_ISU_METHD_TP_CD"
    }, {
        cid: "STK_KIND_CD",
        cnm: "cmb_ISU_SCHDL_STK_KIND_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (scwin.TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     BZ_PROCS_NO : scwin.vBzProcsNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Newlisting.do",
        ref : "dts_secuIsu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_secuIsu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TR_JOB_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        //        alert("dts_secuIsu :"+dts_secuIsu.Text);
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_secuIsu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        await scwin.trs(TR_JOB_UPDATE);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    const secuYn = chk_secuYn.getValue();
    if (secuYn === "Y") {
        dts_secuIsu.setCellData(1, "KONEX_SECU_ISU_YN", "Y");
        if (cmb_KONEX_SECU_ISU_METHD_TP_CD.getValue() === '') {
            await $c.win.alert('증권발행방식이 입력되지 않았습니다.');
            cmb_KONEX_SECU_ISU_METHD_TP_CD.focus();
            return false;
        }
        if (cmb_ISU_SCHDL_STK_KIND_CD.getValue() === '') {
            await $c.win.alert('발행예정주식종류가 입력되지 않았습니다.');
            cmb_ISU_SCHDL_STK_KIND_CD.focus();
            return false;
        }
        if (edt_ISU_SCHDL_SHRS.getValue() === '') {
            await $c.win.alert('발행예정주식수가 입력되지 않았습니다.');
            edt_ISU_SCHDL_SHRS.focus();
            return false;
        }
        if (edt_ISU_NXT_SHRS.getValue() === '') {
            await $c.win.alert('발행후주식수가 입력되지 않았습니다.');
            edt_ISU_NXT_SHRS.focus();
            return false;
        }
        if (edt_ISU_NXT_CAP.getValue() === '') {
            await $c.win.alert('발행후자본금이 입력되지 않았습니다.');
            edt_ISU_NXT_CAP.focus();
            return false;
        }
        if (edt_PAY_SCHDL_DD.getValue() === '') {
            await $c.win.alert('납입예정일자가 입력되지 않았습니다.');
            edt_PAY_SCHDL_DD.focus();
            return false;

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

        } /*ORG SRC: dts_secuIsu.nameValue("1", "KONEX_SECU_ISU_METHD_TP_CD") = getObjectValue(cmb_KONEX_SECU_ISU_METHD_TP_CD);*/ X = cmb_KONEX_SECU_ISU_METHD_TP_CD.getValue(); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_STK_KIND_CD") = getObjectValue(cmb_ISU_SCHDL_STK_KIND_CD);*/ X = cmb_ISU_SCHDL_STK_KIND_CD.getValue(); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_SHRS") = getObjectValue(edt_ISU_SCHDL_SHRS);*/ X = edt_ISU_SCHDL_SHRS.getValue(); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_SHRS") = getObjectValue(edt_ISU_NXT_SHRS);*/ X = edt_ISU_NXT_SHRS.getValue(); /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_CAP") = getObjectValue(edt_ISU_NXT_CAP);*/ X = edt_ISU_NXT_CAP.getValue(); /*ORG SRC: dts_secuIsu.nameValue("1", "PAY_SCHDL_DD") = getObjectValue(edt_PAY_SCHDL_DD);*/ X = edt_PAY_SCHDL_DD.getValue();
    } else {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        dts_secuIsu.setCellData(1, "KONEX_SECU_ISU_YN", "N"); /*ORG SRC: dts_secuIsu.nameValue("1", "KONEX_SECU_ISU_METHD_TP_CD") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_STK_KIND_CD") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_SCHDL_SHRS") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_SHRS") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "ISU_NXT_CAP") = '';*/ X = ''; /*ORG SRC: dts_secuIsu.nameValue("1", "PAY_SCHDL_DD") = '';*/ X = '';
    }
    return true;
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_read_sync = $c.frame.path("../").fn_read_sync;
    fr_fn_read_sync();
};
